<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Jadwal Operasi - RS Mutiara Aini</title><style>
*{box-sizing:border-box}html,body{margin:0;width:100%;height:100%;font-family:Arial,Helvetica,sans-serif;color:#063f6a;background:#effbff;overflow:hidden}.screen{width:100vw;height:100vh;display:flex;flex-direction:column}.head{height:8.1vh;display:grid;grid-template-columns:31% 38% 31%;align-items:center;background:#effbff}.brand{height:100%;display:flex;align-items:center;padding-left:2.3vw}.brand img{width:20vw;max-width:380px}.title{border-left:5px solid #064b7e;height:75%;display:flex;flex-direction:column;justify-content:center;padding-left:5.2vw}.title h1{margin:0;font-size:2.7vw;line-height:.95;font-weight:800;color:#064b7e}.title small{font-size:1vw;font-weight:700;letter-spacing:.18vw;color:#064b7e}.clock{justify-self:end;margin-right:2.1vw;border:1px solid #47748f;border-radius:11px;padding:.45vh 1.3vw;text-align:center;background:#fff;line-height:1}.clock .date{font-size:.75vw;font-weight:700}.clock .time{font-size:1.75vw;font-weight:900;color:#064b7e;margin-top:.25vh}.clock .time span{font-size:1vw}.table-wrap{height:56.8vh;background:#fff}.grid{width:100%;height:100%;border-collapse:separate;border-spacing:0;table-layout:fixed}.grid th{background:#07558e;color:#fff;font-size:1.55vw;padding:1.1vh .35vw;border-right:2px solid #7e8e99;line-height:1.05}.grid td{font-size:.95vw;font-weight:700;text-align:center;padding:.6vh .35vw;border-right:2px solid #73828c;border-bottom:1px solid #fff;line-height:1.02;overflow:hidden}.grid tbody tr:nth-child(odd) td{background:#d7ebf8}.grid tbody tr:nth-child(even) td{background:#fff}.name{text-align:left!important;padding-left:2.1vw!important;font-size:1.03vw!important}.small{font-size:.58vw;display:block;margin-top:.2vh}.ok{display:inline-block;border-radius:8px;color:#fff;padding:.65vh .7vw;font-size:1vw;min-width:4vw}.ok1{background:#1284df}.ok2{background:#0bb52e}.ok3{background:#9c0abf}.cito{background:#ef1010;color:#fff;border-radius:10px;padding:.7vh .7vw;display:inline-block;font-size:.95vw}.footer{height:35.1vh;background:#effbff;border-top:1px solid #999;display:flex;flex-direction:column}.foot-title{height:4.2vh;display:grid;grid-template-columns:14% 67% 19%;background:#07558e;color:#fff;font-weight:800;font-size:1.1vw;align-items:center}.foot-title>div{height:100%;display:flex;align-items:center;justify-content:center;border-right:2px solid #fff}.foot-grid{display:grid;grid-template-columns:14% 67% 19%;flex:1}.shift-col{display:grid;grid-template-rows:repeat(4,1fr)}.shift-name{display:flex;align-items:center;justify-content:center;font-size:1vw;font-weight:900;border-right:2px solid #73828c;border-bottom:1px solid #fff}.shift-name:nth-child(odd){background:#d7ebf8}.staff-col{display:grid;grid-template-rows:repeat(4,1fr)}.staff-row{display:grid;grid-template-columns:repeat(5,1fr);align-items:center;border-bottom:1px solid #fff;font-size:.82vw;font-weight:700}.staff-row:nth-child(odd){background:#d7ebf8}.staff-row span{text-align:center}.oncall{border-left:0}.oncall-row{height:100%;background:#d7ebf8}.loading{position:absolute;inset:0;display:grid;place-items:center;background:#effbff;font-size:2vw;font-weight:800;z-index:5}.hidden{display:none!important}
</style></head><body>
<button id="fs" title="Fullscreen TV" onclick="goFull()" style="position:fixed;right:10px;top:10px;z-index:20;border:0;border-radius:8px;padding:8px 12px;background:rgba(7,85,142,.9);color:#fff;cursor:pointer">⛶</button><div class="screen"><div id="loading" class="loading">Memuat jadwal...</div><div class="head"><div class="brand"><img src="{{ asset('images/logo-rsma.png') }}"></div><div class="title"><h1>Jadwal Operasi</h1><small>R u m a h  S a k i t  M u t i a r a  A i n i</small></div><div class="clock"><div class="date" id="dateText"></div><div class="time" id="timeText"></div></div></div><div class="table-wrap"><table class="grid"><colgroup><col style="width:4.1%"><col style="width:14%"><col style="width:6.8%"><col style="width:6.3%"><col style="width:6.4%"><col style="width:11.8%"><col style="width:10.5%"><col style="width:12.1%"><col style="width:11.5%"><col style="width:11.7%"><col style="width:5%"></colgroup><thead><tr><th>No</th><th>Nama Pasien</th><th>Jenis<br>Kelamin</th><th>OK</th><th>Jam</th><th>Diagnosa</th><th>Tindakan</th><th>Operator</th><th>Anastesi</th><th>Tim Bedah</th><th>CITO</th></tr></thead><tbody id="rows"></tbody></table></div><div class="footer"><div class="foot-title"><div>Shift</div><div>Dinas</div><div>On Call</div></div><div class="foot-grid"><div class="shift-col" id="shiftNames"></div><div class="staff-col" id="staffRows"></div><div class="oncall"><div class="oncall-row"></div></div></div></div></div>
<script>
const fmtDate=new Intl.DateTimeFormat('id-ID',{weekday:'long',day:'2-digit',month:'long',year:'numeric'});const pad=n=>String(n).padStart(2,'0');
function tick(){let n=new Date();document.getElementById('dateText').textContent=fmtDate.format(n);document.getElementById('timeText').innerHTML=`${pad(n.getHours())} : ${pad(n.getMinutes())} <span>WIB</span>`}tick();setInterval(tick,1000);
function age(d){if(!d)return'';let b=new Date(d+'T00:00:00'),n=new Date(),a=n.getFullYear()-b.getFullYear();if(n.getMonth()<b.getMonth()||(n.getMonth()==b.getMonth()&&n.getDate()<b.getDate()))a--;return a}
function render(data){const rows=document.getElementById('rows');rows.innerHTML='';data.schedules.forEach((s,i)=>{const p=s.patient||{};let ok=(s.ok_level||'OK 1').replace(' ','').toLowerCase();rows.insertAdjacentHTML('beforeend',`<tr><td>${i+1}</td><td class="name">${p.name||'-'}<span class="small">${p.birth_date||''} (${age(p.birth_date)} Tahun)</span></td><td>${p.gender||'-'}</td><td><span class="ok ${ok}">${s.ok_level||'-'}</span></td><td>${String(s.operation_time||'').slice(0,5)} WIB</td><td>${s.diagnosis||'-'}</td><td>${s.procedure||'-'}</td><td>${s.operator?.name||'-'}</td><td>${s.anesthesia?.name||'-'}</td><td>${s.surgical_team?.name||'-'}</td><td>${s.cito?'<span class="cito">CITO</span>':''}</td></tr>`)});for(let i=data.schedules.length;i<8;i++)rows.insertAdjacentHTML('beforeend','<tr><td>&nbsp;</td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td><td></td></tr>');const shifts=data.shifts||[];document.getElementById('shiftNames').innerHTML=shifts.slice(0,4).map(s=>`<div class="shift-name">${s.name}</div>`).join('')+Array(Math.max(0,4-shifts.length)).fill('<div class="shift-name"></div>').join('');document.getElementById('staffRows').innerHTML=shifts.slice(0,4).map(s=>{let m=s.members||[];return `<div class="staff-row">${[0,1,2,3,4].map(i=>`<span>${m[i]||''}</span>`).join('')}</div>`}).join('')+Array(Math.max(0,4-shifts.length)).fill('<div class="staff-row"></div>').join('');document.getElementById('loading').classList.add('hidden')}
async function load(){try{let d=new Date(),q=d.toISOString().slice(0,10);let r=await fetch('{{ route('display.events') }}?date='+q,{cache:'no-store'});render(await r.json())}catch(e){document.getElementById('loading').textContent='Gagal memuat data jadwal'} }load();setInterval(load,30000);function goFull(){const e=document.documentElement;if(e.requestFullscreen)e.requestFullscreen().catch(()=>{});document.getElementById('fs').classList.add('hidden')}document.addEventListener('fullscreenchange',()=>{if(document.fullscreenElement)document.getElementById('fs').classList.add('hidden');else document.getElementById('fs').classList.remove('hidden')});
</script></body></html>
